-- ============================================================
-- Medical products import from:
--   all companies product list.pdf (FAISAL ENTERPRISES)
-- NEW catalog vs TEAM A/B - different supplier codes and mostly
-- different companies/products. Safe to import alongside prior SQL.
-- barcode = Enlist/Code | sale_price = Retail | size = Pack
-- SET @tenant_id and @created_by before run
-- ============================================================

SET NAMES utf8mb4;
SET @tenant_id := 1;  -- <<< change to your real tenant_id
SET @created_by := 1; -- <<< change to your user id
SET @now := NOW();

START TRANSACTION;

-- -------------------- COMPANIES --------------------
INSERT INTO `companies` (`company_name`, `tenant_id`, `created_at`, `created_by`, `updated_at`)
SELECT 'AMSON VACCINES & PHARMA (PVT) LTD', @tenant_id, @now, @created_by, @now
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM `companies`
  WHERE `company_name` = 'AMSON VACCINES & PHARMA (PVT) LTD'
    AND (`tenant_id` = @tenant_id OR `tenant_id` IS NULL)
  LIMIT 1
);
