-- Company: AMSON VACCINES & PHARMA (PVT) LTD (139 products)
INSERT INTO `products` (`company_id`, `product_name`, `barcode`, `size`, `sale_price`, `old_purchase_price`, `new_purchase_price`, `stock_balance`, `tenant_id`, `created_at`, `created_by`, `updated_at`)
SELECT c.`id`, 'AIRFLO 5MG TAB', '88001', '14''S', 191.25, 0, 0, 0, @tenant_id, @now, @created_by, @now
FROM `companies` c
WHERE c.`company_name` = 'AMSON VACCINES & PHARMA (PVT) LTD'
  AND c.`tenant_id` = @tenant_id
  AND NOT EXISTS (
    SELECT 1 FROM `products` p
    WHERE p.`tenant_id` = @tenant_id
      AND (p.`barcode` = '88001' OR (p.`company_id` = c.`id` AND p.`product_name` = 'AIRFLO 5MG TAB'))
    LIMIT 1
  )
LIMIT 1;
